use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Keys the subscription store may hold the list under, in order of preference.
const KEYS: [&str; 4] = ["urls", "subscriptions", "feeds", "list"];

/// Percent-encode a string for use as a query-string value.
fn encode_query(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Collect the string literals of a JSON array of strings.
fn parse_json_strings(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '"' {
            continue;
        }
        let mut cur = String::new();
        let mut closed = false;
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    closed = true;
                    break;
                }
                '\\' => match chars.next() {
                    Some('n') => cur.push('\n'),
                    Some('t') => cur.push('\t'),
                    Some('r') => cur.push('\r'),
                    Some('b') => cur.push('\u{0008}'),
                    Some('f') => cur.push('\u{000C}'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            match chars.next().and_then(|h| h.to_digit(16)) {
                                Some(d) => code = code * 16 + d,
                                None => break,
                            }
                        }
                        if let Some(ch) = char::from_u32(code) {
                            cur.push(ch);
                        }
                    }
                    Some(other) => cur.push(other),
                    None => break,
                },
                other => cur.push(other),
            }
        }
        if closed {
            out.push(cur);
        }
    }
    out
}

/// Parse a stored value: a JSON array of strings, or a newline/comma/space-separated list.
fn parse_urls(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    let candidates: Vec<String> = if trimmed.starts_with('[') {
        parse_json_strings(trimmed)
    } else {
        trimmed
            .lines()
            .filter(|line| !line.trim_start().starts_with('#'))
            .flat_map(|line| line.split(|c: char| c == ',' || c.is_whitespace()))
            .map(|p| p.to_string())
            .collect()
    };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let u = c.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment lookup for the input. RunInfo has no text field, so the date is used.
        // A transport failure is a value and is ignored: the output does not depend on it.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&info.date)
        );
        let _ = http_client::fetch(&enrich_url);

        let mut urls: Vec<String> = Vec::new();
        for key in KEYS.iter() {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        SubscriptionList { urls }
    }
}

export!(Node);
